package scp_candidate.Factory_Flow

import org.sireum._
import art.Art
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait ProtectedWorkPriorityResolver_supervisorProcess_protectedWorkPriorityResolver_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_protectedWorkPriorityResolver)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_protectedWorkPriorityResolver)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_protectedWorkPriorityResolver)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_protectedWorkPriorityResolver)
  }

  /** helper function to set the values of all input ports.
   * @param admission payload for data port admission
   * @param protectionContext payload for data port protectionContext
   */
  def put_concrete_inputs(admission : Factory_Flow.AdmissionFact,
                          protectionContext : Factory_Flow.ProtectionContext): Unit = {
    put_admission(admission)
    put_protectionContext(protectionContext)
  }


  /** helper function to check ProtectedWorkPriorityResolver_supervisorProcess_protectedWorkPriorityResolver's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param intentFact method that will be called with the value of the outgoing data
   *        port 'intentFact'.
   */
  def check_concrete_output(intentFact: Factory_Flow.FlowIntentFact => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val intentFactValue: Factory_Flow.FlowIntentFact = get_intentFact().get
    if(!intentFact(intentFactValue)) {
      testFailures = testFailures :+ st"'intentFact' did not match expected: value of the outgoing data port is ${intentFactValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_admission(value : Factory_Flow.AdmissionFact): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_protectedWorkPriorityResolver.operational_api.admission_Id, Factory_Flow.AdmissionFact_Payload(value))
  }

  // setter for in DataPort
  def put_protectionContext(value : Factory_Flow.ProtectionContext): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_protectedWorkPriorityResolver.operational_api.protectionContext_Id, Factory_Flow.ProtectionContext_Payload(value))
  }

  // getter for out DataPort
  def get_intentFact(): Option[Factory_Flow.FlowIntentFact] = {
    val value: Option[Factory_Flow.FlowIntentFact] = get_intentFact_payload() match {
      case Some(Factory_Flow.FlowIntentFact_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port intentFact.  Expecting 'Factory_Flow.FlowIntentFact_Payload' but received ${v}")
      case _ => None[Factory_Flow.FlowIntentFact]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_intentFact_payload(): Option[Factory_Flow.FlowIntentFact_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_protectedWorkPriorityResolver.initialization_api.intentFact_Id).asInstanceOf[Option[Factory_Flow.FlowIntentFact_Payload]]
  }

}
